#[inline]
fn destack_random_stream_export_replay(
    context: &RuntimeCallContext,
    out: *mut RandomStreamState,
    stream: RandomStream,
) -> RuntimeResult<()> {
    let _ = &stream;

    context.replay().run_binding_with_payload_policy(
        RANDOM_STREAM_EXPORT,
        context.replay_payload_for(RANDOM_STREAM_EXPORT)?,
        || unsafe { platform_runtime_native::destack_random_stream_export(context, out, stream) },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_version = result_value.version;
                let result_recorded_bytes_raw = unsafe { result_value.bytes.as_slice()? };
                let mut result_recorded_bytes = Vec::with_capacity(result_recorded_bytes_raw.len());
                for result_recorded_bytes_item_value in result_recorded_bytes_raw {
                    let result_recorded_bytes_item = *result_recorded_bytes_item_value;
                    let result_recorded_bytes_item_recorded = result_recorded_bytes_item;
                    result_recorded_bytes.push(result_recorded_bytes_item_recorded);
                }
                let result_recorded = RandomStreamStateReplayRecord {
                    version: result_recorded_version,
                    bytes: result_recorded_bytes,
                };
                let payload = RandomStreamExportReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    RandomStreamExportReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_version = value.version;
                    let mut value_native_bytes_values = Vec::with_capacity(value.bytes.len());
                    for value_native_bytes_item in value.bytes {
                        let value_native_bytes_item_native = value_native_bytes_item;
                        value_native_bytes_values.push(value_native_bytes_item_native);
                    }
                    let value_native_bytes = context.store_array(value_native_bytes_values);
                    let value_native = RandomStreamState {
                        version: value_native_version,
                        bytes: value_native_bytes,
                    };
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

